class Fredagsaftag {
    private $db;

    function __construct() {
        $this->db = new PDO('mysql:host=localhost;dbname=fredagsaftag', 'brugernavn', 'adgangskode');
    }

    function bestill($medlem) {
        $stmt = $this->db->prepare('INSERT INTO medlemmer SET medlem = :medlem, tid = :tid');
        $stmt->bindParam(':medlem', $medlem);
        $stmt->bindParam(':tid', date('Y-m-d'));
        $stmt->execute();
    }

    function aflever($medlem) {
        $stmt = $this->db->prepare('SELECT * FROM medlemmer WHERE medlem = :medlem');
        $stmt->bindParam(':medlem', $medlem);
        $stmt->execute();
        $result = $stmt->fetch();
